CREATE COLUMN TABLE "TEST_AP"."OLNG" ("Code" INTEGER CS_INT NOT NULL , "ShortName" NVARCHAR(3) NOT NULL , "Name" NVARCHAR(30), "SysLang" INTEGER CS_INT, "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, PRIMARY KEY ("Code")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "OLNG_SHORT_NAME" ON "TEST_AP"."OLNG" ( "ShortName" ASC )